// PRD P12.5 / P12.6a / P12.6c — claim-to-buy: market claims and limit claims over a reward balance.
// Pure matching and aggregation; execution (the buy) is the claims worker / claim program.
export type ClaimKind = 'market' | 'limit'
export type ClaimStatus = 'open' | 'filled' | 'cancelled' | 'expired'

export interface Claim {
  id: string
  wallet: string
  kind: ClaimKind
  amountSol: number // balance to convert
  maxPriceUsd: number | null // limit: never buy above this POT price
  filledSol: number
  potMicro: bigint // POT delivered so far
  status: ClaimStatus
  createdAt: Date
  expiresAt: Date | null
}

export interface LadderBand { maxPriceUsd: number; minPriceUsd: number; totalSol: number; claims: number }

/** Open limit claims aggregated by price band (no wallets). Bands are [k·step, (k+1)·step). */
export function claimLadder(claims: Claim[], stepUsd: number): LadderBand[] {
  const bands = new Map<number, LadderBand>()
  for (const c of claims) {
    if (c.status !== 'open' || c.kind !== 'limit' || c.maxPriceUsd === null) continue
    const k = Math.floor(c.maxPriceUsd / stepUsd)
    const b = bands.get(k) ?? { minPriceUsd: k * stepUsd, maxPriceUsd: (k + 1) * stepUsd, totalSol: 0, claims: 0 }
    b.totalSol += c.amountSol - c.filledSol; b.claims++
    bands.set(k, b)
  }
  return [...bands.values()].sort((a, b) => b.minPriceUsd - a.minPriceUsd)
}

export interface Fill { claimId: string; wallet: string; sol: number }

/**
 * Which open claims may execute now. Market claims always qualify; limit claims only when the
 * current POT price ≤ maxPriceUsd. Oldest first; `budgetSol` caps the worker's hot wallet per run;
 * the last fill may be partial. Expired limits are returned separately.
 */
export function matchClaims(claims: Claim[], potPriceUsd: number, budgetSol: number, now: Date | number): { fills: Fill[]; expired: string[] } {
  const t = typeof now === 'number' ? now : now.getTime()
  const fills: Fill[] = []
  const expired: string[] = []
  let left = budgetSol
  const open = claims.filter((c) => c.status === 'open').sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime() || (a.id < b.id ? -1 : 1))
  for (const c of open) {
    if (c.expiresAt && c.expiresAt.getTime() <= t) { expired.push(c.id); continue }
    if (c.kind === 'limit' && (c.maxPriceUsd === null || !(potPriceUsd > 0) || potPriceUsd > c.maxPriceUsd)) continue
    const want = c.amountSol - c.filledSol
    if (want <= 0 || left <= 0) continue
    const sol = Math.round(Math.min(want, left) * 1e9) / 1e9 // lamport precision
    fills.push({ claimId: c.id, wallet: c.wallet, sol })
    left -= sol
  }
  return { fills, expired }
}

/** Apply a fill (what the worker actually bought). */
export function applyFill(c: Claim, sol: number, potMicro: bigint): Claim {
  const filledSol = Math.min(c.amountSol, c.filledSol + sol)
  return { ...c, filledSol, potMicro: c.potMicro + potMicro, status: filledSol >= c.amountSol - 1e-12 ? 'filled' : c.status }
}

/** Validation for a new claim against the wallet's balance and other open claims. */
export function validateClaim(input: { kind: ClaimKind; amountSol: number; maxPriceUsd?: number | null; expiresAt?: Date | null }, balanceSol: number, openSol: number, now: Date | number): string | null {
  if (!(input.amountSol > 0)) return 'Amount must be positive.'
  if (input.amountSol > balanceSol - openSol + 1e-12) return `Amount exceeds the free reward balance (${Math.max(0, balanceSol - openSol).toFixed(6)} SOL after open claims).`
  if (input.kind === 'limit' && !(input.maxPriceUsd !== null && input.maxPriceUsd !== undefined && input.maxPriceUsd > 0)) return 'Limit claims need maxPriceUsd > 0.'
  const t = typeof now === 'number' ? now : now.getTime()
  if (input.expiresAt && input.expiresAt.getTime() <= t) return 'expiresAt is in the past.'
  return null
}

export const totalUnclaimedSol = (ledgers: { creditedSol: number; claimedSol: number }[]) => ledgers.reduce((s, l) => s + Math.max(0, l.creditedSol - l.claimedSol), 0)
